  slide.addText(String(n).padStart(2, '0'), { x: 12.35, y: 7.08, w: 0.48, h: 0.25, margin: 0, fontSize: 7.5, color: C.muted, bold: true, align: 'right' });
}

function panel(slide, x, y, w, h, fill='FFFFFF') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.08, fill: { color: fill }, line: { color: 'DDE5EF', transparency: 15 }, shadow });
}

function metric(slide, x, y, w, h, value, label, color=C.teal, suffix='') {
  panel(slide, x, y, w, h);
  slide.addText(value, { x: x+0.12, y: y+0.16, w: w-0.24, h: h*0.44, margin: 0, fontSize: 30, bold: true, color, fit: 'shrink' });
  if (suffix) slide.addText(suffix, { x: x+w-0.52, y: y+0.31, w: 0.35, h: 0.22, margin: 0, fontSize: 8, color: C.slate, bold: true });
  slide.addText(label, { x: x+0.14, y: y+h*0.60, w: w-0.28, h: h*0.28, margin: 0, fontSize: 8.5, color: C.slate, fit: 'shrink' });
}

function drawBar(slide, x, y, w, h, value, max, color, label, valLabel, opts={}) {
  slide.addText(label, { x, y: y-0.01, w: opts.labelW || 1.55, h, margin: 0, fontSize: opts.fontSize || 8.2, color: C.ink, bold: opts.bold || false, fit: 'shrink' });
  const bx = x + (opts.labelW || 1.55) + 0.18;
  const bw = w - (opts.labelW || 1.55) - 0.74;
  slide.addShape(pptx.ShapeType.roundRect, { x: bx, y: y+0.05, w: bw, h: h*0.45, rectRadius: 0.04, fill: { color: C.ice }, line: { color: C.ice } });
  slide.addShape(pptx.ShapeType.roundRect, { x: bx, y: y+0.05, w: bw * value / max, h: h*0.45, rectRadius: 0.04, fill: { color }, line: { color, transparency: 100 } });
  slide.addText(valLabel, { x: bx+bw+0.12, y: y-0.01, w: 0.55, h, margin: 0, fontSize: opts.fontSize || 8.2, color: C.ink, bold: true, align: 'right' });
}

function addAxis(slide, x, y, w, h, xLabel, yLabel) {
  slide.addShape(pptx.ShapeType.line, { x, y: y+h, w, h: 0, line: { color: C.grid, width: 1 } });
  slide.addShape(pptx.ShapeType.line, { x, y, w: 0, h, line: { color: C.grid, width: 1 } });
  slide.addText(xLabel, { x: x+w/2-1.2, y: y+h+0.34, w: 2.4, h: 0.2, fontSize: 7.2, color: C.slate, align: 'center', margin: 0 });
  slide.addText(yLabel, { x: x-0.72, y: y+h/2-0.08, w: 0.4, h: 0.18, fontSize: 7.2, color: C.slate, rotate: 270, margin: 0, fit: 'shrink' });
}

function drawScatter(slide, x, y, w, h, points, xMin, xMax, yMin, yMax, opts={}) {
  addAxis(slide, x, y, w, h, opts.xLabel || 'Average years experience', opts.yLabel || 'Median salary (USD)');
  const yTicks = opts.yTicks || [0, 40, 80, 120];
  yTicks.forEach(t => {
    const py = y + h - (t - yMin) / (yMax - yMin) * h;
    slide.addShape(pptx.ShapeType.line, { x, y: py, w, h: 0, line: { color: C.grid, width: 0.4, transparency: 18 } });
    slide.addText(`$${t}K`, { x: x-0.48, y: py-0.08, w: 0.36, h: 0.15, fontSize: 6.4, color: C.muted, align: 'right', margin: 0 });
  });
  (opts.xTicks || [0, 5, 10, 15, 20]).forEach(t => {
    const px = x + (t - xMin) / (xMax - xMin) * w;
    slide.addShape(pptx.ShapeType.line, { x: px, y, w: 0, h, line: { color: C.grid, width: 0.3, transparency: 45 } });
    slide.addText(`${t}`, { x: px-0.12, y: y+h+0.08, w: 0.24, h: 0.15, fontSize: 6.4, color: C.muted, align: 'center', margin: 0 });
  });
  points.forEach(p => {
    const px = x + (p.x - xMin) / (xMax - xMin) * w;
    const py = y + h - (p.y - yMin) / (yMax - yMin) * h;
    const r = p.r || 0.13;
    slide.addShape(pptx.ShapeType.ellipse, { x: px-r/2, y: py-r/2, w: r, h: r, fill: { color: p.color || C.teal, transparency: p.transparency || 0 }, line: { color: 'FFFFFF', width: 0.8 } });
    if (p.label) {
      slide.addText(p.label, { x: px+(p.dx || 0.07), y: py+(p.dy || -0.16), w: p.lw || 1.0, h: 0.15, margin: 0, fontSize: p.fs || 5.9, color: p.labelColor || C.ink, bold: p.bold || false, fit: 'shrink' });
    }
  });
}

function addImageCard(slide, imgPath, x, y, w, h, caption) {
  panel(slide, x, y, w, h + 0.32);
  slide.addImage({ path: imgPath, x: x+0.08, y: y+0.08, w: w-0.16, h: h-0.02, sizingCrop: false });
  slide.addText(caption, { x: x+0.12, y: y+h+0.13, w: w-0.24, h: 0.16, fontSize: 6.4, color: C.muted, margin: 0, italic: true, fit: 'shrink' });
}

